<script setup lang="ts">import{onMounted,ref}from'vue';import{request}from'../api/client';interface Group{id:number;name:string;channel_id:string;owner_name:string;member_count:number;all_muted:boolean;status:string}interface Member{user_id:number;username:string;nickname:string;role:string;muted_until?:string}const groups=ref<Group[]>([]),members=ref<Member[]>([]),selected=ref<Group|null>(null),target=ref<Member|null>(null),action=ref('mute_member'),reason=ref(''),until=ref('');async function load(){groups.value=await request<Group[]>('/v1/ops/groups')}async function open(g:Group){selected.value=g;members.value=await request<Member[]>(`/v1/ops/groups/${g.id}/members`)}async function submit(){if(!selected.value)return;await request(`/v1/ops/groups/${selected.value.id}/control`,{method:'POST',body:JSON.stringify({action:action.value,user_id:target.value?.user_id??0,reason:reason.value,until:until.value?new Date(until.value).toISOString():null})});target.value=null;await load();if(selected.value)await open(selected.value)}onMounted(load)</script>
<template><div class="page"><div class="heading"><div><h1>好友与群聊</h1><p>群资料、成员、禁言和解散</p></div><button @click="load">刷新</button></div><div class="split"><div class="table"><table><thead><tr><th>群聊</th><th>成员</th><th>状态</th></tr></thead><tbody><tr v-for="g in groups" :key="g.id" @click="open(g)"><td><strong>{{g.name}}</strong><small>{{g.channel_id}}</small></td><td>{{g.member_count}}</td><td>{{g.status}}</td></tr></tbody></table></div><section v-if="selected" class="members"><div class="member-head"><div><h2>{{selected.name}}</h2><small>群主 {{selected.owner_name}}</small></div><button @click="target=null;action='dissolve'">解散</button></div><div v-for="m in members" :key="m.user_id" class="member"><span><strong>{{m.nickname}}</strong><small>@{{m.username}} · {{m.role}}</small></span><button v-if="m.role!=='owner'" class="link" @click="target=m;action=m.muted_until?'unmute_member':'mute_member'">管理</button></div></section></div><div v-if="selected&&(target||action==='dissolve')" class="backdrop" @click.self="target=null;action=''" ><form class="dialog" @submit.prevent="submit"><h2>{{action==='dissolve'?'解散群聊':'成员管理'}}</h2><label v-if="action!=='dissolve'">操作<select v-model="action"><option value="mute_member">禁言</option><option value="unmute_member">解除禁言</option><option value="remove_member">移出群聊</option></select></label><label v-if="action==='mute_member'">截止时间（留空为永久）<input v-model="until" type="datetime-local"></label><label>原因<textarea v-model.trim="reason" required minlength="2"></textarea></label><div class="actions"><button type="button" @click="target=null;action=''">取消</button><button class="primary">确认</button></div></form></div></div></template>
<style scoped>@import '../design/admin-page.css';.split{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(320px,1fr);gap:18px}.members{background:#fff;border:1px solid var(--bim-border)}.member-head,.member{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--bim-border)}.member-head h2{margin:0;font-size:17px}.member span{display:grid}.member small,.member-head small{color:var(--bim-muted);margin-top:3px}@media(max-width:900px){.split{grid-template-columns:1fr}}</style>
